CREATE TYPE "EmailStatus" AS ENUM ('scheduled', 'processing', 'sent', 'failed');
CREATE TABLE "Sender" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "smtpConfigurationRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Sender_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Schedule" ("id" TEXT NOT NULL, "senderId" TEXT NOT NULL, "idempotencyKey" TEXT NOT NULL, "delayBetweenEmailsMs" INTEGER NOT NULL, "maxEmailsPerHour" INTEGER NOT NULL, "startTime" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Schedule_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Email" ("id" TEXT NOT NULL, "scheduleId" TEXT NOT NULL, "senderId" TEXT NOT NULL, "recipientEmail" TEXT NOT NULL, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "scheduledTime" TIMESTAMP(3) NOT NULL, "sentTime" TIMESTAMP(3), "status" "EmailStatus" NOT NULL DEFAULT 'scheduled', "attemptCount" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "bullmqJobId" TEXT NOT NULL, "messageId" TEXT, "previewUrl" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Email_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Sender_email_key" ON "Sender"("email"); CREATE INDEX "Sender_active_idx" ON "Sender"("active"); CREATE UNIQUE INDEX "Schedule_idempotencyKey_key" ON "Schedule"("idempotencyKey"); CREATE INDEX "Schedule_senderId_createdAt_idx" ON "Schedule"("senderId", "createdAt"); CREATE UNIQUE INDEX "Email_bullmqJobId_key" ON "Email"("bullmqJobId"); CREATE UNIQUE INDEX "Email_scheduleId_recipientEmail_key" ON "Email"("scheduleId", "recipientEmail"); CREATE INDEX "Email_status_scheduledTime_idx" ON "Email"("status", "scheduledTime"); CREATE INDEX "Email_senderId_status_scheduledTime_idx" ON "Email"("senderId", "status", "scheduledTime");
ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "Sender"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Email" ADD CONSTRAINT "Email_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "Schedule"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Email" ADD CONSTRAINT "Email_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "Sender"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
